30	bool verify(std::vector<float, aligned_allocator<float>> &sw_results,
31	            std::vector<float, aligned_allocator<float>> &hw_results,
32	            unsigned int size) 
33	{
34	    bool check = true;
35	    for (unsigned int i=0; i<size; ++i) {
36	        if (sw_results[i] != hw_results[i]) {
37	            std::cout << "Error: Result mismatch"
38	                      << std::endl;
39	            std::cout << "i = " << i
40	                      << " CPU result = " << sw_results[i]
41	                      << " FPGA result = " << hw_results[i]
42	                      << " Error delta = " << std::abs(sw_results[i]-hw_results[i])
43	                      << std::endl;
44	            check = false;
45	        }
46	    }
47	    return check;
48	}
