50	void Generate_sw_verif_data(std::vector<float, aligned_allocator<float>> &query,
51	                            std::vector<float, aligned_allocator<float>> &searchSpace,
52	                            std::vector<float, aligned_allocator<float>> &kNearstNeighbors,
53	                            unsigned int num_of_points)
54	{
55	    // Generate random float data
56	    std::fill(query.begin(), query.end(), 0.0);    
57	    std::fill(searchSpace.begin(), searchSpace.end(), 0.0);
58	    std::fill(kNearstNeighbors.begin(), kNearstNeighbors.end(), 0.0);
59	
60	    for (unsigned int i=0; i<INPUT_DIM; ++i){
61	        query[i] = static_cast <float>(rand()) / static_cast<float>(RAND_MAX);
62	    }
63	    for (unsigned int i=0; i<num_of_points*INPUT_DIM; ++i){
64	        searchSpace[i] = static_cast <float>(rand()) / static_cast<float>(RAND_MAX);
65	    }
66	
67	    // Calculate distance result
68	    float delta_squared_sum=0.0;
69	    float delta=0.0;
70	    std::vector<float, aligned_allocator<float>> distance(num_of_points);
71	    for (unsigned int i=0; i<num_of_points; ++i){
72	        delta_squared_sum = 0.0;    
73	        for (unsigned int j=0; j<INPUT_DIM; ++j){
74	            delta = query[j] - searchSpace[i*INPUT_DIM+j];
75	            delta_squared_sum += delta * delta;
76	        }
77	        //distance[i] = std::sqrt(delta_squared_sum);
78			distance[i] = delta_squared_sum;
79	    }
80	
81	    // Sort distance
82	    std::sort(distance.begin(), distance.end());    
83	    for (int i(0); i<TOP; ++i){
84	        kNearstNeighbors[i] = distance[TOP-1-i];
85	    }
86	
87	    return;
88	}
